syntax:
pthread_create(&thread, &attr, start_routine, arg);
//Create a new thread
pthread_join(thread, &status); //Wait for thread to finish
pthread_exit(status); //Terminate thread
pthread_detach(thread); //Detach a thread (no need to join)

code_example:
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

void *thread_function(void *arg) {
  long tid = (long)arg;
  printf("Thread %ld: starting\n", tid);
  /* ... some computation ... */
  printf("Thread %ld: finishing\n", tid);
  pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
  pthread_t thread1, thread2;
  long t1 = 1, t2 = 2;
  pthread_create(&thread1, NULL, thread_function, (void *)t1);
  pthread_create(&thread2, NULL, thread_function, (void *)t2);
  pthread_join(thread1, NULL);
  pthread_join(thread2, NULL);
  printf("Main thread: finishing\n");
  return 0;
}
